package com.example.smartpantrymanager.data; import android.database.*;import java.util.*;import com.example.smartpantrymanager.model.*; public class RecipeMatcher { public static List<Recipe> find(DatabaseHelper db){Set<String> have=new HashSet<>();for(PantryItem p:db.all())if(p.quantity>0)have.add(p.name.trim().toLowerCase());List<Recipe> out=new ArrayList<>();Cursor c=db.getReadableDatabase().query("recipe",null,null,null,null,null,"recipe_name");while(c.moveToNext()){Recipe r=new Recipe(c.getLong(0),c.getString(1),c.getString(2));Cursor i=db.getReadableDatabase().query("recipe_ingredient",new String[]{"ingredient_name"},"recipe_id=?",new String[]{String.valueOf(r.id)},null,null,null);boolean ok=true;while(i.moveToNext()){String x=i.getString(0).toLowerCase();r.ingredients.add(x);if(!have.contains(x))ok=false;}i.close();if(ok)out.add(r);}c.close();return out;} }